export declare function ownerKeyFor(scope: WorkspaceCollectionScope, user: AuthUser): string;
/** 共享集合写权限：须持有 owner/admin/member 任一租户角色（纯 viewer 只读） */
export declare function canWriteShared(user: AuthUser): boolean;
/** data 序列化体积（UTF-8 字节） */
export declare function jsonByteLength(data: unknown): number;
